export const GLOSSARY_SHARD = Object.freeze({"satoshi":{"slug":"satoshi","cat":"basics","en":"Satoshi (sats)","contentLocale":"tr","term":"Satoshi (sats)","aka":["sat","sats","satoşi"],"short":"Satoshi (sats), Bitcoin'in en küçük birimidir; 1 BTC 100.000.000 satoshi'ye eşittir ve adını Bitcoin'in takma adlı yaratıcısı Satoshi Nakamoto'dan alır.","body":[[["Bitcoin","bitcoin"]," sekiz ondalık basamağa kadar bölünebilir. 0,00000001 BTC, yani bir satoshi, ağda gönderilebilecek en küçük birimdir. Bu sayede Bitcoin fiyatı ne kadar yüksek olursa olsun küçük tutarlarla işlem yapabilirsiniz."],"Küçük tutarlarda satoshi ile düşünmek ondalık karışıklığını azaltır. 0,0005 BTC yazmak yerine 50.000 sats demek daha okunaklıdır. Bazı cüzdanlar ve Lightning Network uygulamaları bakiyeyi varsayılan olarak sats cinsinden gösterir.","Bitcoin ağındaki işlem ücretleri de genellikle satoshi cinsinden ifade edilir: sat/vB, yani sanal bayt başına satoshi. Bu oran ne kadar yüksekse işleminiz madenciler tarafından o kadar önce bloğa eklenir."],"example":["BTC'nin 50.000 ",["USDT","usdt"]," olduğu bir anda düzenli olarak 25 USDT'lik alım yaptığınızı düşünün. 25 / 50.000 = 0,0005 BTC eder, bu da 50.000 satoshi'dir. Ayda 4 alım yaparsanız ayda 200.000 sats biriktirirsiniz. Bu bakiyeyi cüzdanınıza göndermek için 10 sat/vB oranında ve yaklaşık 140 vB boyutunda bir işlem yaparsanız ücret 1.400 sats, yani yaklaşık 0,7 USDT olur."],"mistakes":["Ondalık basamakları yanlış sayıp 0,0005 BTC ile 0,005 BTC'yi karıştırmak.","Çok küçük satoshi bakiyelerini sık sık cüzdana çekip ücretin tutarın önemli bir kısmını yemesine izin vermek.","Satoshi'nin ayrı bir kripto para olduğunu sanmak; satoshi yalnızca BTC'nin alt birimidir."],"faq":[{"q":"1 Bitcoin kaç satoshi?","a":"1 BTC tam olarak 100.000.000 satoshi'dir. Dolayısıyla 1 satoshi 0,00000001 BTC eder."},{"q":"Satoshi ile Bitcoin alınabilir mi?","a":"Satoshi zaten Bitcoin'in kendisidir, ayrı bir coin değildir. Borsada küçük bir tutarla BTC aldığınızda aslında belli sayıda satoshi almış olursunuz."}],"title":"Satoshi (sats) nedir? 1 BTC kaç satoshi?","description":"Bitcoin'in en küçük birimi satoshi'yi, 1 BTC'nin kaç sats ettiğini ve işlem ücretlerinde neden sat/vB kullanıldığını öğrenin.","related":[["bitcoin","Bitcoin (BTC)","Bitcoin (BTC), 2009'da Satoshi Nakamoto takma adıyla başlatılan, iş ispatı ile çalışan ve toplam arzı 21 milyon BTC ile sınırlı olan ilk ve piyasa değeri en büyük kripto paradır."],["dollar-cost-averaging","Düzenli alım stratejisi (DCA)","DCA (dollar-cost averaging), fiyatı tahmin etmeye çalışmadan belirli aralıklarla sabit tutarda kripto alarak ortalama maliyeti zamana yayma stratejisidir."],["market-order","Piyasa emri (market order)","Piyasa emri (market order), fiyat belirtmeden verilen ve emir defterindeki en iyi mevcut fiyatlardan hemen gerçekleşen alım veya satım emridir."],["cryptocurrency","Kripto para (cryptocurrency)","Kripto para, bir merkez bankası ya da şirket yerine bir blockchain ağı tarafından kaydı tutulan, kriptografiyle korunan ve internet üzerinden doğrudan kişiden kişiye gönderilebilen dijital bir varlıktır."]],"lesson":{"id":"E01","slug":"can-i-buy-part-of-a-bitcoin","ep":1,"title":"Bir bitcoin o kadar pahalıyken yine de biraz alabilir miyim?"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"fomo":{"slug":"fomo","cat":"basics","en":"FOMO","contentLocale":"tr","term":"FOMO (fırsatı kaçırma korkusu)","aka":["FOMO","fırsatı kaçırma korkusu","fomo yapmak"],"short":"FOMO (fear of missing out), hızla yükselen bir coini kaçırma korkusuyla plansız, aceleci ve çoğu zaman yükselişin geç bir aşamasında alım yapma eğilimidir.","body":["FOMO genellikle bir coin birkaç gün içinde sert yükseldiğinde, sosyal medyada herkes kazancını paylaşırken ortaya çıkar. Fiyat ne kadar hızlı yükselirse, beklemek o kadar kayıp gibi hissettirir ve insanlar analiz yapmadan piyasa emriyle alıma girer.",["Sorun, bu tür alımların çoğu zaman yükselişin zirvesine yakın gerçekleşmesidir. Erken alıcılar kâr alırken geç gelenler sert bir düzeltmenin ortasında kalabilir. FOMO, kaldıraçla birleştiğinde ",["likidasyon","liquidation"]," riskini de büyütür."],"FOMO'ya karşı en etkili araç önceden yazılmış bir plandır: hangi koşulda alacağınızı, pozisyonun portföyünüzün yüzde kaçı olacağını ve nerede zarar durduracağınızı işlemden önce belirlemek. Kademeli alım yapmak da tek bir yanlış zamanlamanın etkisini azaltır."],"example":["Bir token üç günde 1 ",["USDT","usdt"],"'den 2,5 USDT'ye çıkıyor ve siz plansız biçimde 1.000 USDT ile 400 token alıyorsunuz. Ertesi hafta fiyat 1,6 USDT'ye geri çekiliyor ve pozisyonunuz 640 USDT'ye iniyor; yüzde 36 kayıp. Aynı parayı planlı biçimde 4 eşit parçaya bölüp 2,5, 2,2, 1,9 ve 1,6 USDT'den alsaydınız ortalama maliyetiniz yaklaşık 1,99 USDT olurdu ve 1,6 USDT'deki kaybınız yaklaşık yüzde 20 ile sınırlı kalırdı."],"mistakes":["Sosyal medyadaki kazanç ekran görüntülerine bakarak araştırmadan alım yapmak.","Yükselişin zirvesinde tüm parayla ve piyasa emriyle tek seferde girmek.","Kaçırdığınız yükselişi telafi etmek için kaldıraç oranını artırmak."],"faq":[{"q":"FOMO yapmak ne demek?","a":"Bir fırsatı kaçırma korkusuyla plansız ve aceleci şekilde alım yapmak anlamına gelir. Kripto topluluklarında fiyat sert yükselirken sıkça kullanılır."},{"q":"FOMO'dan nasıl kaçınılır?","a":"İşlemden önce giriş, pozisyon büyüklüğü ve çıkış kurallarını yazmak ve bunlara uymak en etkili yöntemdir. Kademeli alım ve limit emirler de duygusal kararları azaltır."}],"title":"FOMO nedir? Kriptoda fomo yapmak ne demek?","description":"FOMO'nun ne olduğunu, neden yükselişin zirvesinde alım yaptırdığını ve önceden yazılmış bir planla nasıl kontrol edileceğini öğrenin.","related":[["fud","FUD (korku, belirsizlik ve şüphe)","FUD (fear, uncertainty and doubt), bir kripto para veya proje hakkında korku, belirsizlik ve şüphe yaratan haberler, söylentiler ya da yorumlar için kullanılan bir terimdir."],["bull-market","Boğa piyasası (bull market)","Boğa piyasası (bull market), fiyatların uzun bir dönem boyunca genel olarak yükseldiği, yatırımcı iyimserliğinin ve işlem hacminin arttığı piyasa evresidir."],["position-sizing","Pozisyon büyüklüğü (Position sizing)","Pozisyon büyüklüğü, bir işleme ne kadar sermaye ayıracağınızı zarar durdur seviyenize ve kabul edebileceğiniz en yüksek kayba göre belirleme yöntemidir."],["fear-and-greed-index","Korku ve Açgözlülük Endeksi (Fear and Greed Index)","Korku ve Açgözlülük Endeksi, kripto piyasasındaki genel duyguyu 0 ile 100 arasında tek bir sayıyla gösteren; 0 aşırı korkuyu, 100 aşırı açgözlülüğü ifade eden bir göstergedir."],["stop-loss","Zarar durdur (stop-loss) emri","Zarar durdur (stop-loss) emri, fiyat önceden belirlediğiniz bir tetik seviyesine ulaştığında pozisyonunuzu otomatik olarak kapatarak kaybınızı sınırlamayı amaçlayan bir emirdir."]],"lesson":{"id":"E16","slug":"position-sizing-basics","ep":16,"title":"Ne kadar alacağınıza karar vermeden önce ne kadar kaybedebileceğinizi belirleyin"},"coin":null,"tool":null,"cta":false},"wash-trading":{"slug":"wash-trading","cat":"trading","en":"Wash trading","contentLocale":"tr","term":"Wash trading (Sahte işlem)","aka":["hayali işlem","sahte hacim","wash trade"],"short":"Wash trading, aynı kişinin veya iş birliği yapan tarafların kendi kendine alıp satarak gerçek bir talep yokken yapay işlem hacmi ve fiyat hareketi yaratmasıdır.","body":["Wash trading'de varlığın gerçek sahibi değişmez. Bir hesap satar, aynı kişi ya da ona bağlı başka bir hesap geri alır. Amaç bir coinin veya borsanın olduğundan daha popüler ve likit görünmesini sağlamak, sıralama sitelerinde üst sıralara çıkmak ya da yeni yatırımcıları çekmektir.",["Bu uygulama geleneksel piyasalarda yasaktır ve kripto piyasalarında da birçok ülkede piyasa dolandırıcılığı veya manipülasyon olarak değerlendirilir; kurallar ülkeden ülkeye farklıdır. ",["NFT","nft"]," pazarlarında ödül veya puan toplamak için yapılan sahte alım satımlar da sık görülmüştür."],"Sizin için asıl risk, gerçekte olmayan bir likiditeye güvenmektir. Sahte hacmi olan bir coinde büyük bir satış yapmak istediğinizde defterin aslında neredeyse boş olduğunu görebilirsiniz."],"example":["Bir borsada küçük bir coinin günlük hacmi 30 milyon ",["USDT","usdt"]," görünüyor, ama emir defterinde fiyatın yüzde 2 yakınında toplam yalnızca 40.000 USDT'lik emir var. Günlük hacim, bu derinliğin 750 katı. Bu kadar ince bir defterle bu hacmin gerçek olması pek olası değildir. Aynı coin büyük ve denetimli borsalarda günde yalnızca 300.000 USDT hacim görüyorsa, ilk borsadaki rakamın büyük kısmının yapay olduğundan şüphelenmek için güçlü bir nedeniniz vardır."],"mistakes":["Sıralama sitelerindeki hacim rakamını bir borsanın güvenilirliğinin kanıtı saymak.","Hacmi emir defteri derinliği ve makasla karşılaştırmadan likidite olduğunu varsaymak.","Aynı fiyatta, aynı büyüklükte ve düzenli aralıklarla tekrarlanan işlemleri fark etmemek."],"faq":[{"q":"Wash trading nasıl anlaşılır?","a":"Hacim ile emir defteri derinliği arasındaki uçurum, sürekli aynı büyüklükteki işlemler ve diğer borsalarla çok farklı hacim rakamları tipik işaretlerdir. Bağımsız veri sağlayıcıların düzeltilmiş hacim verileri de yardımcı olur."},{"q":"Wash trading yasal mı?","a":"Birçok ülkede piyasa manipülasyonu sayılır ve yasaktır. Kripto için kurallar ülkeye göre değişir, ancak düzenlemeler bu alanı giderek daha fazla kapsıyor."}],"title":"Wash trading nedir? Sahte işlem hacmi nasıl anlaşılır","description":"Wash trading'in ne olduğunu, sahte hacmin neden yaratıldığını ve bir coinde bunu nasıl fark edeceğinizi öğrenin.","related":[["trading-volume","İşlem hacmi (Trading volume)","İşlem hacmi, belirli bir sürede, genellikle 24 saatte, bir varlığın ne kadarının alınıp satıldığını gösteren toplam miktardır."],["liquidity","Likidite (Liquidity)","Likidite, bir varlığın fiyatı fazla etkilenmeden ne kadar hızlı ve kolay alınıp satılabildiğini gösteren ölçüdür."],["proof-of-reserves","Rezerv kanıtı (proof of reserves)","Rezerv kanıtı (PoR), bir kripto borsasının kullanıcılarına ait bakiyeleri karşılayacak kadar varlığı gerçekten tuttuğunu, zincir üstü adresler ve kriptografik yöntemlerle göstermeye çalıştığı denetim raporudur."],["market-maker","Piyasa yapıcı (Market maker)","Piyasa yapıcı, emir defterinde sürekli alış ve satış emirleri vererek likidite sağlayan ve kazancını çoğunlukla alış-satış makasından elde eden kişi veya şirkettir."]],"lesson":null,"coin":null,"tool":"/exchanges","cta":false},"whale":{"slug":"whale","cat":"trading","en":"Whale","contentLocale":"tr","term":"Balina (Whale)","aka":["kripto balinası","whale"],"short":"Balina, tek başına piyasayı etkileyebilecek kadar büyük miktarda kripto varlık tutan kişi, şirket veya kurumdur.","body":[["Balina için kesin bir eşik yoktur. ",["Bitcoin","bitcoin"]," için birçok analiz 1.000 BTC ve üzeri tutan adresleri balina olarak sınıflandırır, ancak küçük bir altcoinde birkaç yüz bin dolarlık bir pozisyon bile balina etkisi yaratabilir. Balinalar erken yatırımcılar, fonlar, borsalar veya proje ekipleri olabilir."],"Balina hareketleri zincir üstü (on-chain) analiz araçlarıyla izlenir. Büyük bir miktarın borsaya gönderilmesi satış hazırlığı, borsadan çekilmesi ise uzun vadeli saklama olarak yorumlanabilir. Ancak bu yorumlar her zaman doğru değildir; transfer bir borsanın kendi cüzdanları arasında yapılmış olabilir.",["Likiditesi düşük piyasalarda bir balinanın büyük ",["piyasa emri","market-order"]," fiyatı ciddi şekilde kaydırabilir ve kaldıraçlı pozisyonların zincirleme likidasyonunu tetikleyebilir."]],"example":["Günlük hacmi 2 milyon ",["USDT","usdt"]," olan bir altcoinde bir cüzdan 800.000 USDT değerinde tokenı borsaya gönderiyor. Bu miktar, günlük hacmin yüzde 40'ı demektir. Emir defterinde fiyatın yüzde 5 altına kadar toplam yalnızca 300.000 USDT'lik alış emri varsa, gönderilen tokenların tamamı tek seferde piyasa emriyle satıldığında fiyat yüzde 5'ten fazla düşebilir. Aynı büyüklükteki bir transfer, günlük hacmi milyarlarca dolar olan BTC piyasasında fark edilmez bile."],"mistakes":["Borsaya yapılan her büyük transferi kesin satış sinyali saymak.","Balina takip hesaplarının paylaşımlarını doğrulamadan körü körüne işlem açmak.","Düşük likiditeli coinlerde tek bir büyük cüzdanın fiyatı ne kadar etkileyebileceğini hesaba katmamak."],"faq":[{"q":"Kaç BTC'si olan balina sayılır?","a":"Evrensel bir tanım yoktur. Pek çok analiz platformu 1.000 BTC ve üzerini balina eşiği olarak kullanır, bazıları ise daha düşük eşikler seçer."},{"q":"Balina hareketleri nasıl takip edilir?","a":"Blok zinciri gezginleri ve zincir üstü analiz platformları büyük transferleri ve adres bakiyelerini gösterir. Bir adresin kime ait olduğu her zaman bilinemez, bu yüzden yorumları temkinli yapın."}],"title":"Kripto balina nedir? Balinalar piyasayı nasıl etkiler","description":"Kripto balinasının ne olduğunu, balina hareketlerinin nasıl izlendiğini ve fiyata etkisini öğrenin.","related":[["on-chain-analysis","Zincir üstü analiz (on-chain analiz)","Zincir üstü analiz, blockchain'de herkese açık kayıtlı işlemleri, adres hareketlerini ve borsa akışlarını inceleyerek piyasa davranışını anlamaya çalışan analiz yöntemidir."],["exchange-netflow","Borsa giriş ve çıkışları (netflow)","Borsa giriş ve çıkışları, belirli bir sürede borsa cüzdanlarına yatırılan ve oradan çekilen coin miktarını, netflow ise bu ikisi arasındaki farkı gösteren zincir üstü göstergedir."],["liquidity","Likidite (Liquidity)","Likidite, bir varlığın fiyatı fazla etkilenmeden ne kadar hızlı ve kolay alınıp satılabildiğini gösteren ölçüdür."],["slippage","Kayma (slippage)","Kayma (slippage), bir emrin beklenen fiyat ile gerçekte gerçekleştiği ortalama fiyat arasındaki farktır ve genellikle piyasa emirlerinde, düşük likiditede veya hızlı fiyat hareketlerinde ortaya çıkar."]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"margin-call":{"slug":"margin-call","cat":"derivatives","en":"Margin call","contentLocale":"tr","term":"Teminat tamamlama çağrısı (Margin call)","aka":["margin call","teminat uyarısı","marjin çağrısı"],"short":"Teminat tamamlama çağrısı (margin call), kaldıraçlı pozisyonunuzun teminatı bakım seviyesine yaklaştığında borsanın sizi ek teminat yatırmanız veya pozisyonu küçültmeniz için uyarmasıdır.","body":["Geleneksel piyasalarda margin call, aracı kurumun yatırımcıdan belirli bir sürede ek teminat yatırmasını istemesidir. Kripto borsalarında ise süreç çok daha hızlıdır: uyarı genellikle uygulama bildirimi veya e-posta ile gelir ve size gün değil, bazen dakikalar kalır.","Uyarı aldığınızda üç seçeneğiniz vardır: izole pozisyona ek teminat eklemek, pozisyonu kısmen kapatıp riski azaltmak veya pozisyonu tamamen kapatmak. Hiçbir şey yapmazsanız ve fiyat aleyhinize gitmeye devam ederse borsa pozisyonu otomatik olarak tasfiye eder.",["Sert hareketlerde fiyat uyarı seviyesinden ",["likidasyon","liquidation"]," seviyesine saniyeler içinde gidebilir, bu yüzden uyarı bazen hiç gelmeyebilir ya da geç gelebilir. Uyarı eşikleri ve bildirim ayarları borsaya göre değişir."]],"example":["1.000 ",["USDT","usdt"]," teminatla ",["ETH","ethereum"],"'de 10x long açtınız; nominal değer 10.000 USDT, ",["bakım teminatı","maintenance-margin"]," 50 USDT. Borsa, bakım teminatı kalan teminatınızın yüzde 80'ine ulaştığında uyarı gönderiyor olsun; yani kalan teminat yaklaşık 62,5 USDT'ye, zararınız yaklaşık 940 USDT'ye ulaştığında. Bu anda 500 USDT ek teminat eklerseniz kalan teminatınız 562,5 USDT'ye çıkar ve ",["likidasyon fiyatı","liquidation-price"]," giriş fiyatının yaklaşık yüzde 5'i kadar daha aşağı iner."],"mistakes":["Uyarıyı görmezden gelip piyasanın kendiliğinden döneceğini ummak.","Kaybeden pozisyona sürekli teminat ekleyerek zararı büyütmek.","Bildirimleri kapalı tutup uyarının hiç ulaşmadığını sonradan fark etmek."],"faq":[{"q":"Kripto borsasında margin call gelince ne yapmalıyım?","a":"Ya teminat ekleyin ya da pozisyonu küçültün. Hangi seçeneği seçeceğinizi işlem planınıza ve pozisyonun hâlâ geçerli olup olmadığına göre belirleyin."},{"q":"Margin call ile likidasyon aynı şey mi?","a":"Hayır. Margin call bir uyarıdır; likidasyon ise teminat bakım seviyesinin altına düşünce pozisyonun zorla kapatılmasıdır."}],"title":"Margin call nedir? Teminat tamamlama çağrısı","description":"Kripto borsalarında margin call'un ne zaman geldiğini, likidasyondan farkını ve neler yapabileceğinizi öğrenin.","related":[["maintenance-margin","Bakım teminatı (Maintenance margin)","Bakım teminatı, kaldıraçlı bir pozisyonun açık kalabilmesi için hesapta bulunması gereken asgari teminat seviyesidir; teminat bu seviyenin altına inerse likidasyon başlar."],["liquidation","Likidasyon (Tasfiye)","Likidasyon (tasfiye), kaldıraçlı bir pozisyonun teminatı bakım seviyesinin altına düştüğünde borsanın pozisyonu zorla kapatmasıdır."],["cross-margin","Çapraz marjin (Cross margin)","Çapraz marjin, hesaptaki kullanılabilir bakiyenin tamamının tüm açık pozisyonlar için ortak teminat olarak kullanıldığı marjin modudur."],["leverage","Kaldıraç (Leverage)","Kaldıraç, yatırdığınız teminatın birkaç katı büyüklüğünde pozisyon açmanızı sağlayan ve hem kazancı hem kaybı aynı oranda büyüten bir işlem aracıdır."]],"lesson":{"id":"E20","slug":"maintenance-margin","ep":20,"title":"Teminatınız sıfıra ulaşmadan önce pozisyonunuz neden kapatılabilir?"},"coin":null,"tool":"/liquidations","cta":false},"liquidation":{"slug":"liquidation","cat":"derivatives","en":"Liquidation","contentLocale":"tr","term":"Likidasyon (Tasfiye)","aka":["tasfiye","liquidation","pozisyonun patlaması","likide olmak"],"short":"Likidasyon (tasfiye), kaldıraçlı bir pozisyonun teminatı bakım seviyesinin altına düştüğünde borsanın pozisyonu zorla kapatmasıdır.","body":[["Kaldıraçlı pozisyonunuz zarar ettikçe teminatınız erir. Teminat, işaret fiyatına göre hesaplanan ",["bakım teminatı","maintenance-margin"]," seviyesine indiğinde borsanın likidasyon motoru devreye girer ve pozisyonu piyasada kapatır. Türk kripto topluluğunda buna halk arasında pozisyonun patlaması da denir."],["Likidasyon sırasında genellikle pozisyona ayrılan teminatın tamamını veya büyük kısmını kaybedersiniz; bazı borsalar ek bir likidasyon ücreti de keser. Pozisyon likidasyon fiyatından daha iyi bir fiyatla kapatılırsa artan tutar çoğunlukla sigorta fonuna gider. Daha kötü bir fiyatla kapatılırsa açık sigorta fonundan, o da yetmezse ",["otomatik kaldıraç azaltma (ADL)","auto-deleveraging"]," ile karşılanır."],"Bazı borsalar büyük pozisyonları bir anda değil, kademeli olarak tasfiye eder. Sert piyasa hareketlerinde çok sayıda pozisyonun aynı anda tasfiye edilmesi fiyatı daha da iterek zincirleme likidasyonlara yol açabilir."],"example":["800 ",["USDT","usdt"]," teminatla 20x kaldıraçta 16.000 USDT'lik bir ",["BTC","bitcoin"]," short açıyorsunuz ve giriş fiyatı 64.000 USDT. Bakım teminatı oranı yüzde 0,5 ise bakım teminatı 80 USDT'dir ve 720 USDT'lik zarara dayanabilirsiniz. Pozisyon 0,25 BTC olduğu için bu, fiyatın 2.880 USDT yükselmesi demektir. ",["İşaret fiyatı","mark-price"]," yaklaşık 66.880 USDT'ye ulaştığında pozisyon tasfiye edilir ve 800 USDT teminatın neredeyse tamamı gider."],"mistakes":["Stop-loss koymayıp likidasyonu bir tür stop gibi kullanmak; tasfiye çok daha pahalıya gelir.","Likidasyonun son işlem fiyatına göre tetiklendiğini sanıp işaret fiyatını izlememek.","Çapraz marjinde likidasyonun tüm hesap bakiyesini götürebileceğini hesaba katmamak."],"faq":[{"q":"Likidasyon olursa borçlu kalır mıyım?","a":"Çoğu kripto borsasında kaybınız teminatla sınırlıdır ve aradaki açık sigorta fonu veya ADL ile karşılanır. Yine de borsanızın kullanım şartlarını kontrol edin."},{"q":"Likidasyondan nasıl kaçınılır?","a":"Düşük kaldıraç kullanın, likidasyon fiyatından önce tetiklenecek bir stop-loss koyun ve pozisyon büyüklüğünü hesabınıza göre belirleyin. İzole marjin, kaybı tek bir pozisyonla sınırlamaya yardım eder."}],"title":"Likidasyon (tasfiye) nedir? Neden olur, nasıl önlenir","description":"Kripto vadeli işlemlerde likidasyonun nasıl tetiklendiğini, ne kaybettiğinizi ve tasfiyeden nasıl kaçınacağınızı öğrenin.","related":[["liquidation-price","Likidasyon fiyatı (Liquidation price)","Likidasyon fiyatı, kaldıraçlı bir pozisyonun teminatının bakım seviyesine indiği ve borsanın pozisyonu zorla kapatmaya başladığı işaret fiyatı seviyesidir."],["maintenance-margin","Bakım teminatı (Maintenance margin)","Bakım teminatı, kaldıraçlı bir pozisyonun açık kalabilmesi için hesapta bulunması gereken asgari teminat seviyesidir; teminat bu seviyenin altına inerse likidasyon başlar."],["mark-price","İşaret fiyatı (Mark price)","İşaret fiyatı (mark price), vadeli işlem borsalarının gerçekleşmemiş kâr-zararı ve likidasyonu hesaplamak için kullandığı, manipülasyona karşı dengelenmiş adil fiyattır."],["insurance-fund","Sigorta fonu (Insurance fund)","Sigorta fonu, vadeli işlem borsalarının tasfiye edilen pozisyonların teminatı aşan zararlarını karşılamak ve otomatik kaldıraç azaltmayı (ADL) önlemek için tuttuğu rezerv fondur."],["auto-deleveraging","Otomatik kaldıraç azaltma (ADL)","Otomatik kaldıraç azaltma (ADL), tasfiye edilen bir pozisyonun zararı sigorta fonuyla karşılanamadığında, borsanın karşı taraftaki kârlı ve yüksek kaldıraçlı pozisyonları otomatik olarak kısmen kapatmasıdır."]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"Tasfiye: Zorunlu kapatma butonuna kim bastı?"},"coin":null,"tool":"/liquidations","cta":false},"liquidation-price":{"slug":"liquidation-price","cat":"derivatives","en":"Liquidation price","contentLocale":"tr","term":"Likidasyon fiyatı (Liquidation price)","aka":["tasfiye fiyatı","liquidation price","liq fiyatı"],"short":"Likidasyon fiyatı, kaldıraçlı bir pozisyonun teminatının bakım seviyesine indiği ve borsanın pozisyonu zorla kapatmaya başladığı işaret fiyatı seviyesidir.","body":[["Likidasyon fiyatı giriş fiyatınıza, kaldıraca, pozisyon yönüne, ",["bakım teminatı","maintenance-margin"]," oranına ve marjin moduna bağlıdır. Long pozisyonda likidasyon fiyatı girişin altında, short pozisyonda üstündedir. ",["Kaldıraç","leverage"]," yükseldikçe likidasyon fiyatı girişe yaklaşır."],["İzole marjinde likidasyon fiyatı yalnızca o pozisyonun teminatına göre hesaplanır ve teminat ekledikçe uzaklaşır. Çapraz marjinde ise hesaptaki tüm kullanılabilir bakiye hesaba katıldığından, diğer pozisyonların kâr-zararı ve yeni para girişleri ",["likidasyon","liquidation"]," fiyatını sürekli değiştirir."],["Borsa arayüzündeki likidasyon fiyatı tahmini bir değerdir; ücretler, fonlama ödemeleri ve kademeli bakım teminatı oranları onu kaydırabilir. Tetikleyici olarak ",["son işlem fiyatı","last-price"]," değil işaret fiyatı kullanılır. ",["Stop-loss","stop-loss"]," emrinizi her zaman likidasyon fiyatından önce tetiklenecek şekilde koyun."]],"example":[["ETH","ethereum"]," 2.000 USDT iken izole marjinde 10x kaldıraçla long açıyorsunuz. Basitleştirilmiş formül, long için yaklaşık giriş × (1 − 1/kaldıraç + bakım oranı) şeklindedir. Bakım oranı yüzde 0,5 ise likidasyon fiyatı yaklaşık 2.000 × (1 − 0,1 + 0,005) = 1.810 USDT olur. Aynı pozisyonu 25x ile açsaydınız sonuç 2.000 × (1 − 0,04 + 0,005) = 1.930 USDT olurdu; yalnızca yüzde 3,5'lik bir düşüş tasfiyeye yeterdi."],"mistakes":["Stop-loss'u likidasyon fiyatının ötesine koymak; bu durumda stop hiç tetiklenmez.","Çapraz marjinde likidasyon fiyatının sabit kaldığını varsaymak.","Fonlama ödemelerinin teminatı azaltarak likidasyon fiyatını yaklaştırdığını unutmak."],"faq":[{"q":"Likidasyon fiyatı nasıl hesaplanır?","a":"İzole long için kabaca giriş × (1 − 1/kaldıraç + bakım oranı), short için giriş × (1 + 1/kaldıraç − bakım oranı) kullanılır. Ücretler ve kademeli oranlar nedeniyle borsanın gösterdiği değer biraz farklı olabilir."},{"q":"Likidasyon fiyatını nasıl uzaklaştırırım?","a":"İzole pozisyona teminat ekleyebilir, kaldıracı düşürebilir veya pozisyonun bir kısmını kapatabilirsiniz. Her biri, fiyatın tasfiye seviyesine ulaşması için gereken hareketi büyütür."}],"title":"Likidasyon fiyatı nedir? Nasıl hesaplanır","description":"Likidasyon fiyatının kaldıraç, teminat ve marjin moduna göre nasıl hesaplandığını formül ve örnekle öğrenin.","related":[["liquidation","Likidasyon (Tasfiye)","Likidasyon (tasfiye), kaldıraçlı bir pozisyonun teminatı bakım seviyesinin altına düştüğünde borsanın pozisyonu zorla kapatmasıdır."],["leverage","Kaldıraç (Leverage)","Kaldıraç, yatırdığınız teminatın birkaç katı büyüklüğünde pozisyon açmanızı sağlayan ve hem kazancı hem kaybı aynı oranda büyüten bir işlem aracıdır."],["isolated-margin","İzole marjin (Isolated margin)","İzole marjin, her pozisyona ayrı bir teminat ayrıldığı ve olası kaybın yalnızca o pozisyona bağlanan teminatla sınırlı kaldığı marjin modudur."],["mark-price","İşaret fiyatı (Mark price)","İşaret fiyatı (mark price), vadeli işlem borsalarının gerçekleşmemiş kâr-zararı ve likidasyonu hesaplamak için kullandığı, manipülasyona karşı dengelenmiş adil fiyattır."],["maintenance-margin","Bakım teminatı (Maintenance margin)","Bakım teminatı, kaldıraçlı bir pozisyonun açık kalabilmesi için hesapta bulunması gereken asgari teminat seviyesidir; teminat bu seviyenin altına inerse likidasyon başlar."]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"Tasfiye: Zorunlu kapatma butonuna kim bastı?"},"coin":null,"tool":"/liquidations","cta":false},"long-short-ratio":{"slug":"long-short-ratio","cat":"derivatives","en":"Long/short ratio","contentLocale":"tr","term":"Long/short oranı (Long/short ratio)","aka":["long short oranı","L/S oranı","long-short ratio"],"short":"Long/short oranı, bir vadeli işlem piyasasında long pozisyon tutan hesapların veya pozisyonların short tarafına oranını gösteren bir piyasa duyarlılığı göstergesidir.","body":["Oran 1'in üzerindeyse long tarafı, altındaysa short tarafı daha kalabalıktır. Borsalar bu veriyi farklı şekillerde yayımlar: hesap sayısına göre oran, pozisyon büyüklüğüne göre oran veya yalnızca en büyük işlemcilerin (top trader) oranı. Hangi oranı okuduğunuzu bilmeniz önemlidir.","Unutmayın ki vadeli işlemlerde her long'un karşısında bir short vardır; toplam long ve short büyüklüğü her zaman eşittir. Hesap sayısına göre oran 2 ise, long tutan hesap sayısı short tutanların iki katıdır, ama short tarafındaki hesaplar ortalama olarak daha büyük pozisyon tutuyordur.",["Bazı işlemciler aşırı yüksek oranı kalabalık bir long tarafı ve olası bir long squeeze uyarısı olarak yorumlar. Ancak oran tek başına güvenilir bir yön sinyali değildir; ",["açık pozisyon","open-interest"],", ",["fonlama oranı","funding-rate"]," ve fiyat yapısıyla birlikte değerlendirilmelidir. Veriler yalnızca o borsanın kullanıcılarını yansıtır."]],"example":["Bir borsada ",["BTC","bitcoin"]," ",["perpetual","perpetual-futures"]," kontratında 30.000 hesap long, 15.000 hesap short pozisyonda. Hesap bazlı long/short oranı 30.000 / 15.000 = 2'dir. Toplam açık pozisyon 9.000 BTC ise long ve short taraf her biri 9.000 BTC'dir. Ortalama long hesabı 0,3 BTC, ortalama short hesabı ise 0,6 BTC tutar. Yani daha az sayıda ama daha büyük işlemci short tarafındadır."],"mistakes":["Long/short oranı 2 olunca piyasada iki kat fazla long pozisyon olduğunu sanmak.","Hesap bazlı ve pozisyon bazlı oranları karıştırmak.","Tek bir borsanın oranını tüm piyasanın görünümü gibi yorumlamak."],"faq":[{"q":"Yüksek long/short oranı ne anlama gelir?","a":"Long tutan hesapların sayıca daha fazla olduğunu gösterir. Bazı işlemciler bunu kalabalık bir long tarafı olarak görür, ama tek başına fiyatın düşeceği anlamına gelmez."},{"q":"Long/short oranı nerede görülür?","a":"Birçok büyük borsa kendi veri veya istatistik sayfalarında yayımlar. Bazı veri platformları da farklı borsaların oranlarını bir arada gösterir."}],"title":"Long/short oranı nedir? Nasıl yorumlanır","description":"Long/short oranının nasıl hesaplandığını, hesap ve pozisyon bazlı farkı ve neden tek başına sinyal olmadığını öğrenin.","related":[["open-interest","Açık pozisyon miktarı (Open interest)","Açık pozisyon miktarı (open interest), bir vadeli işlem veya opsiyon piyasasında henüz kapatılmamış toplam kontrat sayısını ya da değerini gösterir."],["funding-rate","Fonlama oranı (Funding rate)","Fonlama oranı, sürekli (perpetual) vadeli kontrat fiyatını spot fiyata yakın tutmak için long ve short pozisyon sahipleri arasında düzenli aralıklarla yapılan ödemenin oranıdır."],["long-and-short","Long ve short pozisyon","Long pozisyon, fiyatın yükselmesinden kazanç sağlamak için açılan alış pozisyonudur; short pozisyon ise fiyatın düşmesinden kazanç sağlamak için açılan satış pozisyonudur."],["short-squeeze","Short squeeze (Açık pozisyon sıkışması)","Short squeeze, fiyatın ani yükselişiyle short pozisyon sahiplerinin zararı kesmek için geri alım yapmak veya tasfiye edilmek zorunda kalması ve bu zorunlu alımların fiyatı daha da yukarı itmesidir."]],"lesson":null,"coin":null,"tool":"/funding-rates","cta":false},"anti-phishing-code":{"slug":"anti-phishing-code","cat":"wallets-security","en":"Anti-phishing code","contentLocale":"tr","term":"Oltalama karşıtı kod (anti-phishing code)","aka":["anti-phishing kodu","anti-phishing code","kimlik avı önleme kodu"],"short":"Oltalama karşıtı kod, borsa hesabınızda belirlediğiniz ve borsanın size gönderdiği gerçek e-postalarda görünen kişisel bir kelimedir; bu kodu içermeyen e-postaların sahte olma ihtimali yüksektir.","body":["Dolandırıcılar borsaların tasarımını birebir kopyalayan e-postalar göndererek \"hesabınız askıya alındı\" veya \"çekim onayı gerekli\" gibi mesajlarla sizi sahte sitelere yönlendirmeye çalışır. Oltalama karşıtı kod, gerçek e-postayı tanımanızı kolaylaştırır.","Binance, OKX, Bybit, Bitget gibi birçok borsa bu özelliği güvenlik ayarlarında sunar. Kodu bir kez belirlersiniz; sonrasında borsanın gönderdiği resmî e-postaların belirli bir bölümünde bu kod yazar. Kodu yalnızca siz ve borsa bilir, bu yüzden sahte e-posta gönderen kişi onu tahmin edemez.","Kod tek başına mutlak koruma sağlamaz. Hesap bilgileriniz zaten ele geçirildiyse saldırgan ayarları görebilir. Ayrıca kod sadece e-postalarda işe yarar; SMS, sosyal medya mesajları veya telefon aramaları için ayrıca dikkatli olmanız gerekir."],"example":[["Oltalama","phishing"]," karşıtı kodunuzu \"MaviKule47\" olarak belirlediğinizi varsayalım. Bir gün \"24 saat içinde doğrulama yapmazsanız 3.000 ",["USDT","usdt"]," bakiyeniz dondurulacak\" diyen bir e-posta alırsınız. E-postada logo ve tasarım tamamen doğru görünüyor, ama MaviKule47 kodu yok. Bağlantıya tıklamazsınız; borsanın uygulamasını doğrudan açıp bildirimlere baktığınızda hiçbir uyarı olmadığını görürsünüz."],"mistakes":["Kodu şifreniz veya kullanıcı adınızla aynı ya da tahmin edilebilir seçmek.","Kod olan bir e-postadaki bağlantıya bile göz atmadan her şeyi onaylamak.","Kodu e-postalardan başka kanallar için de geçerli bir doğrulama sanmak."],"faq":[{"q":"Oltalama karşıtı kod nereden ayarlanır?","a":"Çoğu borsada hesap veya güvenlik ayarları menüsündedir. Konumu ve adı borsaya göre biraz değişebilir."},{"q":"E-postada kod varsa her zaman güvenli mi?","a":"Büyük ihtimalle gerçek bir e-postadır, ancak yine de işlemleri bağlantıya tıklamak yerine uygulamayı veya kayıtlı adresi doğrudan açarak yapmak daha güvenlidir."}],"title":"Oltalama karşıtı kod nedir? Sahte e-posta nasıl anlaşılır?","description":"Anti-phishing kodunun nasıl çalıştığını, sahte borsa e-postalarını tanımaya nasıl yardım ettiğini ve sınırlarını öğrenin.","related":[["phishing","Oltalama (phishing)","Oltalama (phishing), dolandırıcıların sahte web siteleri, e-postalar, mesajlar veya reklamlar kullanarak sizden şifre, 2FA kodu, kurtarma ifadesi almaya ya da zararlı bir işlemi imzalatmaya çalıştığı saldırıdır."],["two-factor-authentication","İki faktörlü doğrulama (2FA)","İki faktörlü doğrulama (2FA), hesabınıza girişte veya çekimde şifrenin yanında ikinci bir kanıt, örneğin bir doğrulama uygulamasından gelen 6 haneli kod istenmesini sağlayan güvenlik katmanıdır."],["withdrawal-whitelist","Çekim beyaz listesi (withdrawal whitelist)","Çekim beyaz listesi, borsa hesabınızdan yalnızca önceden kaydedip onayladığınız adreslere kripto çekilmesine izin veren bir güvenlik ayarıdır."]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"Gerçek kapıyı bul: Körlemesine hesap açma"},"coin":null,"tool":null,"cta":false},"pig-butchering-scam":{"slug":"pig-butchering-scam","cat":"wallets-security","en":"Pig-butchering scam","contentLocale":"tr","term":"Domuz kasaplığı dolandırıcılığı (pig butchering)","aka":["pig butchering","romantik yatırım dolandırıcılığı","sahte yatırım platformu dolandırıcılığı"],"short":"Domuz kasaplığı dolandırıcılığı, dolandırıcının haftalarca güven veya romantik ilişki kurduktan sonra kurbanı sahte bir kripto yatırım platformuna para yatırmaya ikna ettiği ve sonunda tüm parayı aldığı uzun soluklu bir dolandırıcılıktır.","body":["Senaryo genellikle yanlış numaraya gelmiş gibi görünen bir mesajla, bir tanışma uygulamasıyla veya sosyal medya sohbetiyle başlar. Dolandırıcı başarılı, kibar ve sabırlıdır. Bir süre sonra kendi kazançlarından bahseder ve size \"tanıdığı bir platformu\" veya özel bir uygulamayı önerir.",["Sahte platform ekranda yüksek getiri gösterir. Küçük bir çekime izin verilir ki güveniniz artsın. Daha fazla yatırdığınızda çekim aniden \"vergi\", \"teminat\" veya \"",["hesap doğrulama","kyc"]," ücreti\" bahanesiyle engellenir. Ödedikçe yeni bir ücret çıkar; sonunda iletişim kesilir."],"Uyarı işaretleri nettir: internette tanıştığınız biri yatırım öneriyorsa, platform bilinen bir borsa değilse, uygulama resmî mağazalarda yoksa veya çekim için önce ödeme isteniyorsa durun. Gerçek borsalar çekimin önünü açmak için ayrı bir ödeme talep etmez."],"example":["Bir sohbet uygulamasında tanıştığınız kişi sizi bir \"",["arbitraj","arbitrage"]," platformuna\" yönlendiriyor. 500 ",["USDT","usdt"]," yatırıyorsunuz, bir hafta sonra ekranda 650 USDT görünüyor ve 100 USDT'yi sorunsuz çekiyorsunuz. Güvenip 8.000 USDT daha yatırıyorsunuz; bakiye 11.000 USDT görünüyor. Çekmek istediğinizde yüzde 20 \"vergi\", yani 2.200 USDT ön ödeme isteniyor. Bu talep tek başına dolandırıcılığın işaretidir; ödeme yapmak yalnızca kaybı artırır."],"mistakes":["İnternette tanışılan kişinin önerdiği bilinmeyen platformlara para yatırmak.","Ekranda görünen bakiyeyi gerçek para sanmak.","Çekim için istenen \"vergi\" veya \"teminat\" ücretini ödemek."],"faq":[{"q":"Pig butchering neden bu adı taşıyor?","a":"İfade, kurbanın kesimden önce besilenen bir hayvan gibi uzun süre güvenle \"beslenmesini\" ve sonra tüm parasının alınmasını anlatır."},{"q":"Dolandırıldığımı fark edersem ne yapmalıyım?","a":"Ödemeyi durdurun, tüm yazışmaları ve işlem hash'lerini kaydedin ve resmî makamlara başvurun. Paranızı geri getireceğini vaat eden \"kurtarma\" hizmetleri de sıkça ikinci bir dolandırıcılıktır."}],"title":"Domuz kasaplığı (pig butchering) dolandırıcılığı nedir?","description":"Pig butchering dolandırıcılığının adımlarını, sahte yatırım platformlarının uyarı işaretlerini ve nasıl korunacağınızı öğrenin.","related":[["phishing","Oltalama (phishing)","Oltalama (phishing), dolandırıcıların sahte web siteleri, e-postalar, mesajlar veya reklamlar kullanarak sizden şifre, 2FA kodu, kurtarma ifadesi almaya ya da zararlı bir işlemi imzalatmaya çalıştığı saldırıdır."],["rug-pull","Rug pull (halı çekme)","Rug pull, bir kripto projesinin geliştiricilerinin yatırımcı parasını toplayıp likiditeyi çekerek, token'ları satarak veya akıllı sözleşmedeki gizli yetkileri kullanarak projeyi aniden terk ettiği dolandırıcılıktır."],["p2p-trading","P2P alım satım (C2C)","P2P alım satım, kullanıcıların borsanın aracılık ettiği bir pazarda, kripto varlığı birbirlerinden banka transferi gibi ödeme yöntemleriyle doğrudan aldığı veya sattığı işlem türüdür."],["seed-phrase","Kurtarma ifadesi (seed phrase)","Kurtarma ifadesi (seed phrase), bir kripto cüzdanının tüm özel anahtarlarının türetildiği 12 veya 24 kelimelik listedir ve bu kelimeleri bilen herkes cüzdanın tamamını kontrol edebilir."]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"Biri sana para kazandıracağını söylüyor. Önce ne istediğine bak."},"coin":null,"tool":null,"cta":false},"hash-rate":{"slug":"hash-rate","cat":"onchain","en":"Hash rate","contentLocale":"tr","term":"Hash oranı (hash rate)","aka":["hash rate","hashrate","hash gücü","madencilik gücü"],"short":"Hash oranı, iş ispatı (proof of work) kullanan bir ağda madencilerin saniyede yaptığı toplam hash hesaplama sayısıdır ve ağın işlem gücünü ve güvenliğini gösterir.","body":[[["Bitcoin","bitcoin"]," madencileri yeni blok bulmak için sürekli tahmin yapar; her tahmin bir hash hesaplamasıdır. Ağın toplam hash oranı saniyedeki tahmin sayısıdır ve bugün exahash (EH/s, saniyede 10 üzeri 18 hash) cinsinden ifade edilir."],"Hash oranı yükseldikçe ağa saldırmak daha pahalı hâle gelir, çünkü bir saldırganın ağın yarısından fazla işlem gücüne sahip olması gerekir. Bitcoin her 2.016 blokta bir zorluğu ayarlar; böylece hash oranı ne olursa olsun bloklar ortalama 10 dakikada bir bulunur.","Hash oranı madencilerin kârlılığıyla bağlantılıdır. Nisan 2024 yarılanmasıyla blok ödülü 3,125 BTC'ye inince verimsiz makineler zorlandı. Hash oranı fiyatla birebir hareket etmez; bir gösterge olarak ağ sağlığını anlamaya yardım eder."],"example":["Ağın toplam hash oranının 600 EH/s olduğunu ve sizin ",["madencilik","mining"]," çiftliğinizin 6 EH/s ürettiğini düşünelim. Payınız yüzde 1'dir. Günde ortalama 144 blok bulunur ve blok ödülü 3,125 BTC olduğundan günlük toplam ödül 450 BTC eder. Ücretleri saymazsanız sizin beklenen payınız günde 4,5 BTC olur. Ağın hash oranı 750 EH/s'ye çıkarsa payınız yüzde 0,8'e düşer ve aynı makinelerle günde yaklaşık 3,6 BTC beklersiniz."],"mistakes":["Hash oranı rekor kırdı diye fiyatın mutlaka yükseleceğini düşünmek.","Hash oranını proof of stake ağlarında da aynı şekilde aramak; orada güvenlik stake miktarına dayanır.","Zorluk ayarlamasını hesaba katmadan madencilik kârı hesaplamak."],"faq":[{"q":"Hash rate yüksek olması ne anlama gelir?","a":"Ağa daha fazla işlem gücü bağlı olduğu ve saldırmanın daha maliyetli olduğu anlamına gelir. Madencilerin ağa yatırım yapmaya devam ettiğini de gösterir."},{"q":"Hash oranı düşerse ne olur?","a":"Kısa vadede bloklar biraz yavaş bulunur, ardından zorluk düşürülür ve blok süresi tekrar ortalama 10 dakikaya döner."}],"title":"Hash rate nedir? Bitcoin hash oranı anlamı","description":"Hash rate nedir, ağ güvenliğiyle ilişkisi ve madencilik payı nasıl hesaplanır; Bitcoin örneği ve gerçekçi sayılarla öğrenin.","related":[["mining","Kripto madenciliği (mining)","Kripto madenciliği, iş ispatı kullanan blockchain'lerde özel donanımlarla hesaplama yapılarak işlemlerin bloklara eklenmesi ve karşılığında yeni basılan coin ile işlem ücretlerinin kazanılması sürecidir."],["proof-of-work","İş ispatı (Proof of Work, PoW)","İş ispatı (Proof of Work, PoW), madencilerin zor bir matematik bulmacasını çözmek için bilgi işlem gücü harcadığı ve bulmacayı ilk çözenin yeni bloğu ekleyip ödül kazandığı bir blockchain uzlaşma mekanizmasıdır."],["bitcoin-halving","Bitcoin halving (yarılanma)","Bitcoin halving (yarılanma), yaklaşık her dört yılda bir, yani her 210.000 blokta bir, madencilere verilen blok ödülünün kod gereği yarıya indirildiği olaydır."],["on-chain-analysis","Zincir üstü analiz (on-chain analiz)","Zincir üstü analiz, blockchain'de herkese açık kayıtlı işlemleri, adres hareketlerini ve borsa akışlarını inceleyerek piyasa davranışını anlamaya çalışan analiz yöntemidir."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"exchange-netflow":{"slug":"exchange-netflow","cat":"onchain","en":"Exchange inflows and outflows","contentLocale":"tr","term":"Borsa giriş ve çıkışları (netflow)","aka":["exchange netflow","borsa net akışı","borsa girişleri","borsa çıkışları"],"short":"Borsa giriş ve çıkışları, belirli bir sürede borsa cüzdanlarına yatırılan ve oradan çekilen coin miktarını, netflow ise bu ikisi arasındaki farkı gösteren zincir üstü göstergedir.","body":["Analiz platformları bilinen borsa adreslerini etiketler ve bu adreslere giren ve çıkan coin'leri toplar. Netflow pozitifse borsaya daha fazla coin gelmiş, negatifse daha fazla coin çekilmiştir.",["Genel yorum şudur: büyük girişler, insanların satmaya hazırlandığını düşündürebilir; çünkü satmak için coin'i genellikle borsaya göndermek gerekir. Büyük çıkışlar ise coin'lerin uzun süreli saklama için kendi cüzdanlara taşındığını gösterebilir. ",["Stablecoin","stablecoin"]," girişleri ise tersine alım gücünün borsaya geldiği şeklinde okunur."],["Bu yorumlar her zaman geçerli değildir. Borsalar kendi cüzdanları arasında transfer yapar, ETF saklayıcıları coin'leri taşır, yeni adresler henüz etiketlenmemiş olabilir. Netflow'u fiyat, ",["fonlama oranı","funding-rate"]," ve hacimle birlikte değerlendirmek daha sağlıklıdır."]],"example":["Bir gün içinde borsalara 18.000 ",["ETH","ethereum"]," girdiğini ve 12.000 ETH çıktığını varsayalım. Netflow +6.000 ETH'dir. ETH 2.500 dolardan işlem görüyorsa bu yaklaşık 15 milyon dolarlık ek arzın borsalara geldiği anlamına gelir. Aynı gün borsalara 300 milyon dolarlık stablecoin de girmişse tablo karışır: satış için gelen ETH kadar alım için gelen dolar da vardır. Tek göstergeye bakıp 'satış baskısı geliyor' demek bu yüzden eksik bir yorum olur."],"mistakes":["Her büyük borsa girişini mutlaka satış olarak yorumlamak.","Stablecoin akışlarını ve coin akışlarını birlikte değerlendirmemek.","Tek bir günlük veriden uzun vadeli sonuç çıkarmak."],"faq":[{"q":"Borsadan coin çıkışı iyi bir işaret mi?","a":"Çoğu zaman coin'lerin uzun vadeli saklamaya alındığı şeklinde yorumlanır. Ancak borsanın kendi iç transferi de olabilir, bu yüzden kesin bir sinyal değildir."},{"q":"Netflow verisini nereden görebilirim?","a":"CryptoQuant, Glassnode gibi on-chain analiz platformları borsa akışlarını grafiklerle gösterir. Platformlar farklı adres etiketleri kullandığı için rakamlar küçük farklılıklar gösterebilir."}],"title":"Exchange netflow nedir? Borsa giriş ve çıkışları","description":"Borsa giriş ve çıkışları ile netflow nasıl hesaplanır, pozitif ve negatif akış ne anlatır ve nasıl yanıltabilir, öğrenin.","related":[["on-chain-analysis","Zincir üstü analiz (on-chain analiz)","Zincir üstü analiz, blockchain'de herkese açık kayıtlı işlemleri, adres hareketlerini ve borsa akışlarını inceleyerek piyasa davranışını anlamaya çalışan analiz yöntemidir."],["whale","Balina (Whale)","Balina, tek başına piyasayı etkileyebilecek kadar büyük miktarda kripto varlık tutan kişi, şirket veya kurumdur."],["proof-of-reserves","Rezerv kanıtı (proof of reserves)","Rezerv kanıtı (PoR), bir kripto borsasının kullanıcılarına ait bakiyeleri karşılayacak kadar varlığı gerçekten tuttuğunu, zincir üstü adresler ve kriptografik yöntemlerle göstermeye çalıştığı denetim raporudur."],["stablecoin","Stablecoin (sabit coin)","Stablecoin, değerini genellikle ABD doları gibi bir referans varlığa sabitlemeyi amaçlayan ve kripto piyasasında nakit gibi kullanılan bir kripto paradır."]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"active-addresses":{"slug":"active-addresses","cat":"onchain","en":"Active addresses","contentLocale":"tr","term":"Aktif adres sayısı (active addresses)","aka":["aktif adresler","active addresses","günlük aktif adres"],"short":"Aktif adres sayısı, belirli bir sürede, genellikle bir günde, bir blockchain'de işlem gönderen veya alan benzersiz adreslerin sayısıdır ve ağ kullanımını ölçmek için kullanılır.","body":["Bir ağın gerçekten kullanılıp kullanılmadığını anlamanın basit yollarından biri, kaç farklı adresin işlem yaptığına bakmaktır. Günlük aktif adres sayısı arttığında ağa ilginin arttığı, düştüğünde ise azaldığı düşünülür.",["Ancak adres kişi değildir. Bir kullanıcı onlarca adres kullanabilir, bir borsa binlerce müşteriyi tek bir adresten yönetebilir. Ayrıca düşük ücretli ağlarda botlar ve ",["airdrop","airdrop"]," avcıları yapay olarak çok sayıda adres oluşturabilir. Bu yüzden ağlar arasında karşılaştırma yaparken dikkatli olmak gerekir."],["Aktif adres verisi, işlem sayısı, ücret geliri ve ",["toplam kilitli değer","total-value-locked"]," (TVL) gibi göstergelerle birlikte okunduğunda daha anlamlı olur. Ani sıçramalarda bir teşvik kampanyası olup olmadığını kontrol edin."]],"example":"Bir layer 2 ağında günlük aktif adres sayısının bir ay içinde 200.000'den 800.000'e çıktığını görüyorsunuz; artış yüzde 300. Aynı dönemde ağın toplam ücret geliri yalnızca yüzde 20 artmış ve ortalama işlem tutarı 2 dolar civarında kalmış. Bu tablo, gerçek kullanıcı artışından çok airdrop beklentisiyle yapılan küçük işlemlere işaret ediyor olabilir. Kampanya bittiğinde sayı 250.000'e dönerse, kalıcı kullanımın aslında sınırlı olduğunu anlarsınız.","mistakes":["Aktif adres sayısını aktif kullanıcı sayısıyla eşit saymak.","Farklı ücret yapısına sahip ağları sadece adres sayısıyla karşılaştırmak.","Airdrop veya teşvik kampanyası dönemlerindeki ani artışları kalıcı büyüme sanmak."],"faq":[{"q":"Aktif adres sayısı artarsa fiyat yükselir mi?","a":"Doğrudan bir bağlantı yoktur. Artan kullanım ağa ilgiyi gösterebilir ama fiyat birçok başka etkene bağlıdır."},{"q":"Aktif adres nasıl sayılır?","a":"Genellikle seçilen süre içinde başarılı bir işlemde gönderici veya alıcı olarak görünen benzersiz adresler sayılır. Veri sağlayıcılar tanımı biraz farklı yapabilir."}],"title":"Aktif adres sayısı nedir? Ağ kullanımı ölçümü","description":"Aktif adres sayısı nedir, ağ kullanımını nasıl gösterir ve bot veya airdrop işlemleri bu veriyi nasıl şişirir, öğrenin.","related":[["on-chain-analysis","Zincir üstü analiz (on-chain analiz)","Zincir üstü analiz, blockchain'de herkese açık kayıtlı işlemleri, adres hareketlerini ve borsa akışlarını inceleyerek piyasa davranışını anlamaya çalışan analiz yöntemidir."],["wallet-address","Cüzdan adresi (wallet address)","Cüzdan adresi, bir blokzincirde kripto almak için paylaştığınız, açık anahtardan türetilen harf ve rakamlardan oluşan bir dizidir; banka hesap numarasına benzer ama ağa özgüdür."],["trading-volume","İşlem hacmi (Trading volume)","İşlem hacmi, belirli bir sürede, genellikle 24 saatte, bir varlığın ne kadarının alınıp satıldığını gösteren toplam miktardır."],["total-value-locked","Kilitli toplam değer (TVL)","Kilitli toplam değer (TVL), bir DeFi protokolünün veya blokzincirin akıllı sözleşmelerinde yatırılmış olarak duran tüm varlıkların güncel piyasa değeridir."]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"fear-and-greed-index":{"slug":"fear-and-greed-index","cat":"onchain","en":"Fear and Greed Index","contentLocale":"tr","term":"Korku ve Açgözlülük Endeksi (Fear and Greed Index)","aka":["Fear and Greed Index","korku ve açgözlülük endeksi","korku endeksi"],"short":"Korku ve Açgözlülük Endeksi, kripto piyasasındaki genel duyguyu 0 ile 100 arasında tek bir sayıyla gösteren; 0 aşırı korkuyu, 100 aşırı açgözlülüğü ifade eden bir göstergedir.","body":[["Endeks birkaç veriyi birleştirir: ",["fiyat oynaklığı","volatility"],", işlem hacmi ve momentum, sosyal medya etkileşimi, ",["Bitcoin","bitcoin"],"'in piyasa payı ve bazı sürümlerde arama trendleri. En çok bilinen kripto sürümü Alternative.me tarafından yayımlanır; farklı sağlayıcıların hesaplama yöntemleri birbirinden ayrılabilir."],["Genel fikir, kalabalığın duygusunun aşırılara gittiğinde fiyatın da aşırıya kaçabileceğidir. Aşırı korku dönemlerinde panik satışları, aşırı açgözlülük dönemlerinde ",["FOMO","fomo"]," ile geç alımlar sık görülür. Bazı yatırımcılar endeksi kendi duygularını kontrol etmek için bir ayna olarak kullanır."],["Endeks bir zamanlama aracı değildir. Piyasa haftalarca aşırı açgözlülükte kalıp yükselmeye devam edebilir ya da aşırı korkuda daha da düşebilir. ",["Fonlama oranı","funding-rate"]," ve ",["açık pozisyon","open-interest"]," gibi verilerle birlikte bakmak daha anlamlıdır."]],"example":"Endeksin bir hafta içinde 78'den 22'ye düştüğünü varsayalım. Bu, piyasanın açgözlülükten korkuya geçtiğini gösterir. Aynı dönemde fonlama oranı yüzde 0,03'ten yüzde -0,01'e dönmüşse, kaldıraçlı long pozisyonların temizlendiğini de görürsünüz. Planlı alım yapan biri, aylık 1.000 liralık bütçesini değiştirmeden sürdürür; panikle tüm 10.000 liralık portföyünü satan biri ise duyguya göre hareket etmiş olur. Endeks, hangi tarafta olduğunuzu fark etmenize yardım eder.","mistakes":["Endeks 20'nin altına indi diye her seferinde dibin geldiğini düşünmek.","Endeks yüksek diye hemen short açmak; açgözlülük uzun sürebilir.","Farklı sitelerdeki endeks değerlerinin aynı yöntemle hesaplandığını varsaymak."],"faq":[{"q":"Korku ve açgözlülük endeksi nasıl okunur?","a":"0-24 arası aşırı korku, 25-49 korku, 50 civarı nötr, 51-74 açgözlülük ve 75-100 aşırı açgözlülük olarak yorumlanır. Sınırlar sağlayıcıya göre küçük farklılıklar gösterebilir."},{"q":"Aşırı korku alım fırsatı mı?","a":"Bazı yatırımcılar böyle düşünür, ancak endeks tek başına fiyatın döneceğini göstermez. Kendi planınızı ve risk sınırlarınızı korumak daha önemlidir."}],"title":"Korku ve Açgözlülük Endeksi nedir? Nasıl okunur","description":"Kripto Korku ve Açgözlülük Endeksi nedir, 0-100 arası değerler nasıl okunur ve neden tek başına sinyal değildir, öğrenin.","related":[["fomo","FOMO (fırsatı kaçırma korkusu)","FOMO (fear of missing out), hızla yükselen bir coini kaçırma korkusuyla plansız, aceleci ve çoğu zaman yükselişin geç bir aşamasında alım yapma eğilimidir."],["fud","FUD (korku, belirsizlik ve şüphe)","FUD (fear, uncertainty and doubt), bir kripto para veya proje hakkında korku, belirsizlik ve şüphe yaratan haberler, söylentiler ya da yorumlar için kullanılan bir terimdir."],["volatility","Volatilite (oynaklık)","Volatilite (oynaklık), bir varlığın fiyatının belirli bir süre içinde ne kadar ve ne hızla dalgalandığının ölçüsüdür; yüksek volatilite büyük ve ani fiyat hareketleri demektir."],["funding-rate","Fonlama oranı (Funding rate)","Fonlama oranı, sürekli (perpetual) vadeli kontrat fiyatını spot fiyata yakın tutmak için long ve short pozisyon sahipleri arasında düzenli aralıklarla yapılan ödemenin oranıdır."]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"referral-code":{"slug":"referral-code","cat":"exchange-features","en":"Referral code (fee rebate)","contentLocale":"tr","term":"Referans kodu (komisyon iadesi)","aka":["referans kodu","davet kodu","referral code","komisyon iadesi"],"short":"Referans kodu, bir borsaya kaydolurken girilen ve sizi davet eden kişi veya ortakla eşleştiren; çoğu zaman işlem ücretlerinizin bir kısmının size geri ödenmesini sağlayan davet kodudur.","body":["Borsalar yeni kullanıcı getirenlere işlem ücretlerinden pay verir. Bazı referans programlarında bu payın bir kısmı size, davet edilen kullanıcıya, komisyon iadesi (rebate) olarak geri verilir. Böylece aynı işlemleri daha düşük net ücretle yaparsınız.","Kod genellikle sadece kayıt sırasında girilebilir. Hesabı açtıktan sonra eklemek çoğu borsada mümkün değildir. İade oranı, süresi ve hangi ürünleri (spot, vadeli) kapsadığı programa göre değişir; bazı programlarda iade belirli bir süre sonra biter.","Kodu yalnızca güvendiğiniz bir kaynaktan, borsanın resmi kayıt sayfası üzerinden kullanın. Referans bağlantısı gibi görünen sahte siteler giriş bilgilerinizi çalmaya çalışabilir. Adres çubuğundaki alan adını her zaman kontrol edin."],"example":["Ayda 200.000 ",["USDT","usdt"]," vadeli işlem hacmi yaptığınızı ve ortalama taker ücretinin yüzde 0,05 olduğunu varsayalım. Aylık ücretiniz 100 USDT eder. Referans kodunuz ücretlerin yüzde 20'sini iade ediyorsa her ay 20 USDT geri alırsınız ve net ücretiniz 80 USDT'ye düşer. Bir yılda bu 240 USDT eder. Hacminiz yarıya inerse iade de 10 USDT'ye düşer; yani iade, işlem yapmayı kârlı hâle getirmez, sadece maliyeti azaltır."],"mistakes":["Hesap açtıktan sonra referans kodunun eklenebileceğini sanmak.","Sadece iade için gereğinden fazla işlem yapıp toplam ücreti artırmak.","Referans bağlantısının yönlendirdiği sitenin resmi alan adı olup olmadığını kontrol etmemek."],"faq":[{"q":"Referans kodu sonradan girilebilir mi?","a":"Çoğu borsada hayır; kod yalnızca kayıt ekranında girilir. Bazı borsalar kısa bir süre için istisna tanıyabilir, bunu destek ekibine sormak gerekir."},{"q":"Komisyon iadesi nasıl ödenir?","a":"Genellikle günlük veya haftalık olarak USDT ya da borsanın belirlediği bir varlık şeklinde hesabınıza yatırılır. Ödeme takvimi programa göre değişir."}],"title":"Referans kodu nedir? Kripto borsasında komisyon iadesi","description":"Borsa referans kodu nedir, komisyon iadesi işlem ücretinizi nasıl düşürür ve kodu güvenli şekilde nasıl kullanırsınız, öğrenin.","related":[["maker-taker-fees","Maker ve taker ücretleri","Maker ve taker ücretleri, borsanın emir defterine likidite ekleyen (maker) ve defterdeki emirleri anında karşılayarak likidite çeken (taker) işlemlere uyguladığı farklı komisyon oranlarıdır."],["vip-tier","VIP ücret seviyesi","VIP ücret seviyesi, borsaların 30 günlük işlem hacminize veya hesap bakiyenize göre sizi kademelere ayırıp daha yüksek kademede daha düşük maker ve taker ücreti uyguladığı sistemdir."],["centralized-exchange","Merkezi borsa (CEX)","Merkezi borsa (CEX), bir şirket tarafından işletilen, kullanıcıların fonlarını saklayan ve alıcılarla satıcıları kendi emir defterinde eşleştiren kripto para alım satım platformudur."]],"lesson":null,"coin":null,"tool":"/rates","cta":true},"tokenized-treasuries":{"slug":"tokenized-treasuries","cat":"tokenized-assets","en":"Tokenized treasuries","contentLocale":"tr","term":"Tokenize hazine bonoları","aka":["tokenized treasuries","tokenize tahvil","zincir üstü hazine bonosu"],"short":"Tokenize hazine bonoları, ABD Hazine bonosu gibi kısa vadeli devlet borçlanma araçlarına yatırım yapan bir fonun veya yapının paylarını blockchain üzerinde token olarak temsil eden ürünlerdir.","body":[["Klasik ",["stablecoin","stablecoin"],"'ler genellikle rezervlerdeki hazine bonolarının faizini sahiplerine dağıtmaz. Tokenize hazine bonolarında ise faiz geliri, ücretler düşüldükten sonra token sahiplerine yansır. Bu, ya token adedinin artmasıyla ya da token fiyatının zamanla yükselmesiyle olur. BlackRock'un BUIDL fonu ve Ondo Finance'in ürünleri bilinen örneklerdir."],["Bu ürünler genellikle menkul kıymet sayılır. Bu yüzden çoğu yalnızca ",["KYC","kyc"],"'den geçmiş, nitelikli yatırımcılara veya belirli ülkelerdeki kullanıcılara açıktır. Minimum yatırım tutarı yüksek olabilir."],"Riskler: faiz oranı değişimi getiriyi doğrudan etkiler, ihraççı ve saklayıcı riski vardır, token'ı nakde çevirmek belirli işlem saatlerine veya itfa süreçlerine bağlı olabilir. Getiri dolar cinsindendir; TL bazında sonuç kur hareketine de bağlıdır."],"example":["Kısa vadeli hazine bonosu faizinin yıllık yüzde 4,5 ve ürünün yönetim ücretinin yüzde 0,25 olduğunu varsayalım. Net getiri yaklaşık yüzde 4,25'tir. 20.000 ",["USDC","usdc"]," yatırırsanız bir yılda yaklaşık 850 USDC kazanırsınız. Aynı tutarı USDC olarak cüzdanda tutsaydınız faiz almazdınız. Faiz oranı yıl ortasında yüzde 3,5'e düşerse ikinci altı ayın getirisi azalır ve yıllık toplam yaklaşık 750 USDC civarında kalır."],"mistakes":["Tokenize hazine bonosunu bir stablecoin ile aynı şey sanmak.","Getirinin sabit olduğunu düşünmek; faiz oranları değiştikçe getiri değişir.","Erişim şartlarını ve itfa sürelerini okumadan yatırım planlamak."],"faq":[{"q":"Tokenize hazine bonosu stablecoin mi?","a":"Hayır. Değeri 1 dolara yakın seyretse de bir fon payını temsil eder ve faiz getirisi sağlar. Hukuki olarak genellikle menkul kıymettir."},{"q":"Tokenize hazine bonolarının getirisi nereden gelir?","a":"Getiri, fonun tuttuğu kısa vadeli devlet bonolarının faizinden gelir. Yönetim ücretleri düşüldükten sonra token sahiplerine yansıtılır."}],"title":"Tokenize hazine bonosu nedir? Zincir üstü tahvil","description":"Tokenize hazine bonoları nedir, stablecoin'den farkı nedir, faiz getirisi nasıl yansır ve kimler erişebilir, örnekle öğrenin.","related":[["real-world-assets","Gerçek dünya varlıkları (RWA)","Gerçek dünya varlıkları (RWA), devlet tahvilleri, altın, gayrimenkul, krediler veya hisseler gibi blockchain dışındaki varlıkların zincir üstünde token olarak temsil edilmesidir."],["stablecoin","Stablecoin (sabit coin)","Stablecoin, değerini genellikle ABD doları gibi bir referans varlığa sabitlemeyi amaçlayan ve kripto piyasasında nakit gibi kullanılan bir kripto paradır."],["apr-vs-apy","APR ve APY farkı","APR, bileşik etki olmadan hesaplanan basit yıllık getiri oranıdır; APY ise kazancın düzenli olarak yeniden yatırıldığı varsayımıyla bileşik getiriyi gösterir, bu yüzden aynı oran için APY her zaman APR'den yüksek veya ona eşittir."],["kyc","KYC (müşterini tanı)","KYC (Know Your Customer, müşterini tanı), kripto borsalarının ve finansal kuruluşların kullanıcının kimliğini, adresini ve bazen gelir kaynağını doğruladığı zorunlu kimlik doğrulama sürecidir."]],"lesson":null,"coin":{"slug":"ondo","name":"Ondo","symbol":"ONDO"},"tool":"/topics/tokenized-treasuries","cta":false}});
